DROP TABLE IF EXISTS `pedidos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `pedidos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `codigo` varchar(10) DEFAULT NULL,
  `estado` varchar(20) NOT NULL DEFAULT 'Recibido',
  `total` decimal(8,2) NOT NULL,
  `entregado_por` bigint(20) unsigned DEFAULT NULL,
  `entregado_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `pedidos_codigo_unique` (`codigo`),
  KEY `pedidos_user_id_foreign` (`user_id`),
  KEY `pedidos_entregado_por_foreign` (`entregado_por`),
  KEY `pedidos_estado_index` (`estado`),
  CONSTRAINT `pedidos_entregado_por_foreign` FOREIGN KEY (`entregado_por`) REFERENCES `users` (`id`),
  CONSTRAINT `pedidos_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=463 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
